def find_r(limit):
    solutions = []
    for q in range(1, limit + 1):
        for p in range(-limit * 2, limit * 2 + 1):
            if p == 0: continue
            r = p/q
            val = 1 - 6*r**2 + r**4
            if val >= 0:
